import {
  Box,
  Button,
  Container,
  Stack,
  Typography,
} from "@mui/material";
import masterData from "../../data/masterData.json";
import { ArrowForwardIcon, getIcon } from "../../utils/iconMap";
import { scrollToTop as lenisScrollToTop } from "../LenisSmoothScroll";

interface FooterCtaSectionProps {
  onTalkToExpert?: () => void;
}

export default function FooterCtaSection({ onTalkToExpert }: FooterCtaSectionProps) {
  const { footerCta } = masterData;

  const handleTalkToExpert = () => {
    if (onTalkToExpert) {
      onTalkToExpert();
      return;
    }
    lenisScrollToTop(false);
  };

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background: "linear-gradient(135deg, #003E99 0%, #0056D2 50%, #1A6FE8 100%)",
        py: { xs: 5, md: 6 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.15,
          backgroundImage: `url(${footerCta.image})`,
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      />
      <Box
        sx={{
          position: "absolute",
          width: 300,
          height: 300,
          borderRadius: "50%",
          border: "40px solid rgba(255,255,255,0.06)",
          right: -80,
          top: -100,
        }}
      />

      <Container maxWidth="lg" sx={{ position: "relative", zIndex: 1 }}>
        <Stack
          direction={{ xs: "column", md: "row" }}
          spacing={3}
          alignItems={{ xs: "flex-start", md: "center" }}
          justifyContent="space-between"
        >
          <Box
            component="img"
            src={footerCta.image}
            alt="Surgery"
            sx={{
              display: { xs: "none", md: "block" },
              width: 200,
              height: 140,
              objectFit: "cover",
              borderRadius: 2,
              opacity: 0.9,
            }}
          />

          <Box sx={{ flex: 1 }}>
            <Typography
              sx={{
                color: "#fff",
                fontWeight: 800,
                fontSize: { xs: "1.25rem", md: "1.75rem" },
                letterSpacing: "0.02em",
                mb: 0.5,
              }}
            >
              {footerCta.headline}
            </Typography>
            <Typography sx={{ color: "rgba(255,255,255,0.9)", fontSize: { xs: 15, md: 18 } }}>
              {footerCta.subheadline}
            </Typography>
          </Box>

          <Button
            variant="contained"
            endIcon={<ArrowForwardIcon />}
            onClick={scrollToTop}
            sx={{
              bgcolor: "#fff",
              color: "primary.main",
              px: 3,
              py: 1.4,
              borderRadius: 8,
              fontWeight: 700,
              "&:hover": { bgcolor: "#F0F6FF" },
              whiteSpace: "nowrap",
            }}
          >
            {footerCta.buttonLabel}
          </Button>
        </Stack>

        <Stack
          direction="row"
          spacing={{ xs: 3, md: 6 }}
          justifyContent="center"
          sx={{ mt: 4, pt: 3, borderTop: "1px solid rgba(255,255,255,0.2)" }}
        >
          {footerCta.trustPoints.map((point) => {
            const Icon = getIcon(point.icon);
            return (
              <Stack key={point.id} direction="row" spacing={1} alignItems="center">
                <Icon sx={{ color: "#fff", fontSize: 22 }} />
                <Typography sx={{ color: "#fff", fontSize: 13, fontWeight: 500 }}>
                  {point.label}
                </Typography>
              </Stack>
            );
          })}
        </Stack>
      </Container>
    </Box>
  );
}
